define([],function(){'use strict';
/**
 * Moodle-native visual worksheet designer.
 *
 * The production bundle is committed in amd/build so shared-hosting deployments
 * do not need Node.js. It intentionally has no CDN/runtime dependency.
 *
 * @module mod_worksheetgrader/worksheet_designer
 */

const markerLabels = {
    C: 'Ô trả lời ngắn',
    L: 'Ô trả lời dài',
    B: 'Checkbox',
    U: 'Nộp ảnh',
    S: 'Thông tin Moodle',
};

const escapeHtml = value => String(value).replace(/[&<>'"]/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;',
}[character]));

const markerClass = code => `wsg-designer-marker is-${code.charAt(0).toLowerCase()}`;

const markerNode = (documentObject, code) => {
    const node = documentObject.createElement('span');
    node.className = markerClass(code);
    node.dataset.wsgMarker = code;
    node.contentEditable = 'false';
    node.setAttribute('role', 'button');
    node.setAttribute('tabindex', '0');
    node.title = 'Nhấn Delete để xóa trường này';
    node.innerHTML = `<span class="wsg-marker-icon">${code.charAt(0) === 'B' ? '☐' :
        code.charAt(0) === 'U' ? '🖼' : code.charAt(0) === 'L' ? '¶' : '✎'}</span>` +
        `<span>${escapeHtml(markerLabels[code.charAt(0)] || 'Trường')} · ${escapeHtml(code)}</span>`;
    return node;
};

const hydrateMarkers = (html, documentObject) => {
    const template = documentObject.createElement('template');
    template.innerHTML = html || '<p>Bắt đầu thiết kế phiếu tại đây…</p>';
    const walker = documentObject.createTreeWalker(template.content, NodeFilter.SHOW_TEXT);
    const textNodes = [];
    while (walker.nextNode()) {
        textNodes.push(walker.currentNode);
    }
    textNodes.forEach(textNode => {
        const value = textNode.nodeValue || '';
        const regex = /\[\[([CSBLU]\d+)\]\]/g;
        let match;
        let cursor = 0;
        const fragment = documentObject.createDocumentFragment();
        let found = false;
        while ((match = regex.exec(value)) !== null) {
            found = true;
            fragment.appendChild(documentObject.createTextNode(value.slice(cursor, match.index)));
            fragment.appendChild(markerNode(documentObject, match[1]));
            cursor = match.index + match[0].length;
        }
        if (found) {
            fragment.appendChild(documentObject.createTextNode(value.slice(cursor)));
            textNode.replaceWith(fragment);
        }
    });
    return template.innerHTML;
};

const serializeCanvas = canvas => {
    const clone = canvas.cloneNode(true);
    clone.querySelectorAll('[data-wsg-marker]').forEach(node => {
        node.replaceWith(document.createTextNode(`[[${node.dataset.wsgMarker}]]`));
    });
    clone.querySelectorAll('[contenteditable]').forEach(node => node.removeAttribute('contenteditable'));
    clone.querySelectorAll('.wsg-selected-cell').forEach(node => node.classList.remove('wsg-selected-cell'));
    return clone.innerHTML.trim();
};

const maxCode = (html, prefix) => {
    const values = [...String(html || '').matchAll(new RegExp(`(?:\\[\\[|data-wsg-marker=["'])${prefix}(\\d+)`, 'gi'))]
        .map(match => Number(match[1]));
    return values.length ? Math.max(...values) : 0;
};

const createTable = (rows, columns) => {
    const table = document.createElement('table');
    table.className = 'wsg-designed-table';
    table.innerHTML = Array.from({length: rows}, (_, row) => `<tr>${Array.from({length: columns}, (_, column) =>
        row === 0 ? `<th>Tiêu đề ${column + 1}</th>` : '<td>Nhập nội dung</td>').join('')}</tr>`).join('');
    return table;
};

const insertAtSelection = (canvas, node) => {
    canvas.focus();
    const selection = window.getSelection();
    let range = selection && selection.rangeCount ? selection.getRangeAt(0) : null;
    if (!range || !canvas.contains(range.commonAncestorContainer)) {
        range = document.createRange();
        range.selectNodeContents(canvas);
        range.collapse(false);
    }
    range.deleteContents();
    range.insertNode(node);
    range.setStartAfter(node);
    range.collapse(true);
    selection.removeAllRanges();
    selection.addRange(range);
};

const templates = {
    blank: '<h2>PHIẾU HỌC TẬP</h2><p>Lớp: [[S1]] &nbsp; Nhóm: [[S2]]</p><p>Nhập yêu cầu tại đây…</p>',
    questiontable: '<h2>PHIẾU HOẠT ĐỘNG NHÓM</h2><p>Lớp: [[S1]] &nbsp; Nhóm: [[S2]]</p>' +
        '<table class="wsg-designed-table"><tbody><tr><th>Nội dung</th><th>Trả lời</th><th>Ghi chú</th></tr>' +
        '<tr><td>Câu hỏi 1</td><td>[[C1]]</td><td>[[L1]]</td></tr>' +
        '<tr><td>Câu hỏi 2</td><td>[[C2]]</td><td>[[L2]]</td></tr></tbody></table>',
    checklist: '<h2>BẢNG KIỂM</h2><p>Lớp: [[S1]] &nbsp; Nhóm: [[S2]]</p>' +
        '<table class="wsg-designed-table"><tbody><tr><th>Tiêu chí</th><th>Có</th><th>Không</th><th>Lý do</th></tr>' +
        '<tr><td>Tiêu chí 1</td><td>[[B1]]</td><td>[[B2]]</td><td>[[C1]]</td></tr>' +
        '<tr><td>Tiêu chí 2</td><td>[[B3]]</td><td>[[B4]]</td><td>[[C2]]</td></tr></tbody></table>',
    mindmap: '<h2>SƠ ĐỒ TƯ DUY</h2><p>Lớp: [[S1]] &nbsp; Nhóm: [[S2]]</p>' +
        '<p>Nhóm hãy vẽ sơ đồ tư duy theo yêu cầu, chụp ảnh rõ nét và tải lên bên dưới.</p>' +
        '<div class="wsg-upload-prompt"><strong>Ảnh sơ đồ tư duy</strong><br>[[U1]]</div>' +
        '<p>Thuyết minh ngắn: [[L1]]</p>',
};

const init = () => {
    const host = document.getElementById('wsg-worksheet-designer');
    const source = document.getElementById('id_contenthtml');
    const form = host?.closest('form');
    if (!host || !source || !form) {
        return;
    }

    // Keep the raw textarea available when JavaScript fails, but hide it once the
    // visual designer has initialised successfully.
    const sourceContainer = source.closest('.form-group, .mb-3');
    if (sourceContainer) {
        sourceContainer.hidden = true;
    } else {
        source.hidden = true;
    }

    host.innerHTML = `<div class="wsg-designer-shell">
        <div class="wsg-designer-templates">
            <span class="fw-bold">Mẫu nhanh:</span>
            <button type="button" class="btn btn-sm btn-outline-secondary" data-template="blank">Phiếu trống</button>
            <button type="button" class="btn btn-sm btn-outline-secondary" data-template="questiontable">Bảng câu hỏi</button>
            <button type="button" class="btn btn-sm btn-outline-secondary" data-template="checklist">Bảng checkbox</button>
            <button type="button" class="btn btn-sm btn-outline-secondary" data-template="mindmap">Nộp sơ đồ tư duy</button>
        </div>
        <div class="wsg-designer-toolbar" role="toolbar" aria-label="Công cụ thiết kế phiếu">
            <button type="button" data-command="bold" title="In đậm"><strong>B</strong></button>
            <button type="button" data-command="italic" title="In nghiêng"><em>I</em></button>
            <button type="button" data-block="h2">Tiêu đề</button>
            <button type="button" data-block="p">Đoạn văn</button>
            <button type="button" data-action="table">+ Bảng</button>
            <button type="button" data-action="row">+ Hàng</button>
            <button type="button" data-action="column">+ Cột</button>
            <button type="button" data-action="deleterow">− Hàng</button>
            <button type="button" data-action="deletecolumn">− Cột</button>
            <span class="wsg-toolbar-separator"></span>
            <button type="button" data-marker="C">Ô trả lời ngắn</button>
            <button type="button" data-marker="L">Ô trả lời dài</button>
            <button type="button" data-marker="B">Checkbox</button>
            <button type="button" data-marker="U">Nộp ảnh</button>
            <button type="button" data-marker="S">Thông tin Moodle</button>
            <span class="wsg-toolbar-separator"></span>
            <button type="button" data-command="undo">↶</button>
            <button type="button" data-command="redo">↷</button>
        </div>
        <div class="wsg-designer-tabs">
            <button type="button" class="is-active" data-view="visual">Thiết kế trực quan</button>
            <button type="button" data-view="code">Mã HTML</button>
        </div>
        <div class="wsg-designer-canvas" contenteditable="true" role="textbox" aria-multiline="true"></div>
        <textarea class="wsg-designer-code" spellcheck="false" hidden></textarea>
        <div class="wsg-designer-status small text-muted" aria-live="polite"></div>
    </div>`;

    const canvas = host.querySelector('.wsg-designer-canvas');
    const code = host.querySelector('.wsg-designer-code');
    const status = host.querySelector('.wsg-designer-status');
    let activeCell = null;
    let view = 'visual';

    const loadHtml = html => {
        canvas.innerHTML = hydrateMarkers(html, document);
        code.value = html || '';
        status.textContent = 'Đã nạp nội dung vào trình thiết kế.';
    };
    const syncSource = () => {
        const html = view === 'visual' ? serializeCanvas(canvas) : code.value;
        source.value = html;
        if (view === 'visual') {
            code.value = html;
        }
        return html;
    };
    const switchView = target => {
        if (target === view) {
            return;
        }
        if (target === 'code') {
            code.value = serializeCanvas(canvas);
            canvas.hidden = true;
            code.hidden = false;
        } else {
            canvas.innerHTML = hydrateMarkers(code.value, document);
            code.hidden = true;
            canvas.hidden = false;
        }
        view = target;
        host.querySelectorAll('[data-view]').forEach(button =>
            button.classList.toggle('is-active', button.dataset.view === view));
    };

    host.addEventListener('click', event => {
        const button = event.target.closest('button');
        const cell = event.target.closest('td,th');
        if (cell && canvas.contains(cell)) {
            canvas.querySelectorAll('.wsg-selected-cell').forEach(item => item.classList.remove('wsg-selected-cell'));
            cell.classList.add('wsg-selected-cell');
            activeCell = cell;
        }
        if (!button) {
            return;
        }
        if (button.dataset.template) {
            if (canvas.textContent.trim() && !window.confirm('Thay nội dung hiện tại bằng mẫu đã chọn?')) {
                return;
            }
            loadHtml(templates[button.dataset.template]);
            return;
        }
        if (button.dataset.view) {
            switchView(button.dataset.view);
            return;
        }
        if (view !== 'visual') {
            switchView('visual');
        }
        if (button.dataset.command) {
            document.execCommand(button.dataset.command, false);
            canvas.focus();
            return;
        }
        if (button.dataset.block) {
            document.execCommand('formatBlock', false, button.dataset.block);
            canvas.focus();
            return;
        }
        if (button.dataset.marker) {
            const prefix = button.dataset.marker;
            const current = serializeCanvas(canvas);
            const codeValue = `${prefix}${maxCode(current, prefix) + 1}`;
            insertAtSelection(canvas, markerNode(document, codeValue));
            status.textContent = `Đã chèn ${markerLabels[prefix]} ${codeValue}.`;
            return;
        }
        if (button.dataset.action === 'table') {
            const rows = Math.min(20, Math.max(2, Number(window.prompt('Số hàng (gồm hàng tiêu đề):', '3')) || 3));
            const columns = Math.min(10, Math.max(2, Number(window.prompt('Số cột:', '3')) || 3));
            insertAtSelection(canvas, createTable(rows, columns));
            return;
        }
        if (!activeCell) {
            status.textContent = 'Hãy bấm vào một ô bảng trước.';
            return;
        }
        const row = activeCell.closest('tr');
        const table = activeCell.closest('table');
        const columnIndex = [...row.children].indexOf(activeCell);
        if (button.dataset.action === 'row') {
            const newRow = document.createElement('tr');
            [...row.children].forEach(() => {
                const newCell = document.createElement('td');
                newCell.textContent = 'Nhập nội dung';
                newRow.appendChild(newCell);
            });
            row.after(newRow);
        } else if (button.dataset.action === 'column') {
            table.querySelectorAll('tr').forEach((tableRow, index) => {
                const newCell = document.createElement(index === 0 ? 'th' : 'td');
                newCell.textContent = index === 0 ? 'Tiêu đề mới' : 'Nhập nội dung';
                tableRow.appendChild(newCell);
            });
        } else if (button.dataset.action === 'deleterow' && table.rows.length > 1) {
            row.remove();
            activeCell = null;
        } else if (button.dataset.action === 'deletecolumn' && row.children.length > 1) {
            table.querySelectorAll('tr').forEach(tableRow => tableRow.children[columnIndex]?.remove());
            activeCell = null;
        }
    });

    canvas.addEventListener('keydown', event => {
        const marker = event.target.closest?.('[data-wsg-marker]');
        if (marker && (event.key === 'Delete' || event.key === 'Backspace')) {
            marker.remove();
            event.preventDefault();
        }
    });

    form.addEventListener('submit', () => syncSource());
    window.addEventListener('beforeunload', () => syncSource());
    loadHtml(source.value);
};

return {init};
});
